import type { PackageManagerKind } from '@tcn-computer/protocol';
import type { CatalogPackage, ServiceDefinition } from './types.js';

/**
 * Curated registries.
 *
 * Every entry carries a plausible published version, the binaries it puts on
 * PATH, and real dependency ranges, because those three facts are what make
 * `install` observable: a version the user can check, a command they can then
 * run, and a transitive closure the resolver has to work through.
 *
 * Registries are shared where the real world shares them — npm/pnpm/yarn/bun
 * all resolve against npmjs.org, and pip/uv/pipx/poetry all resolve against
 * PyPI — so a package installed with one is the same package under another.
 */

function p(name: string, version: string, description: string, extra: Partial<CatalogPackage> = {}): CatalogPackage {
  return { name, version, description, ...extra };
}

/** Builds the descending version history most registries expose. */
function history(...versions: string[]): readonly string[] { return versions; }

