/** Every registry, keyed by the manager that resolves against it. */
export const registries: Readonly<Record<PackageManagerKind, readonly CatalogPackage[]>> = {
  brew: [...brewFormulae, ...brewCasks],
  mas: masApps,
  apt: aptPackages,
  dpkg: dpkgArchives,
  snap: snapPackages,
  flatpak: flatpakPackages,
  winget: wingetPackages,
  choco: chocoPackages,
  scoop: scoopPackages,
  npm: npmRegistry,
  pnpm: npmRegistry,
  yarn: npmRegistry,
  bun: npmRegistry,
  pip: pypiRegistry,
  // pipx resolves against all of PyPI (a tool's own dependencies land in its
  // venv); only its *listing* is app-focused.
  pipx: pypiRegistry,
  poetry: pypiRegistry,
  uv: pypiRegistry,
  cargo: cargoRegistry,
  go: goRegistry,
  gem: gemRegistry,
  composer: composerRegistry,
  dotnet: dotnetTools,
  nuget: nugetRegistry,
  vcpkg: vcpkgRegistry,
  conda: condaRegistry,
};

const indexCache = new Map<PackageManagerKind, Map<string, CatalogPackage>>();

/** Name/alias → entry, built once per manager. */
export function registryIndex(manager: PackageManagerKind): Map<string, CatalogPackage> {
  const cached = indexCache.get(manager);
  if (cached) return cached;
  const index = new Map<string, CatalogPackage>();
  for (const entry of registries[manager]) {
    index.set(entry.name.toLowerCase(), entry);
    for (const alias of entry.aliases ?? []) if (!index.has(alias.toLowerCase())) index.set(alias.toLowerCase(), entry);
  }
  indexCache.set(manager, index);
  return index;
}

export function findEntry(manager: PackageManagerKind, name: string): CatalogPackage | undefined {
  return registryIndex(manager).get(name.trim().toLowerCase());
}

/** Every version the resolver may pick for an entry, ascending. */
export function availableVersions(entry: CatalogPackage): string[] {
  const versions = new Set<string>(entry.versions ?? []);
  versions.add(entry.version);
  return [...versions];
}

/** Total entries across every registry, counting a shared registry once per manager it serves. */
export function catalogSize(): { managers: number; entries: number; distinct: number } {
  const distinct = new Set<string>();
  let entries = 0;
  for (const [manager, list] of Object.entries(registries)) {
    entries += list.length;
    for (const entry of list) distinct.add(`${manager}/${entry.name}`);
  }
  return { managers: Object.keys(registries).length, entries, distinct: distinct.size };
}
